<?php
require_once __DIR__.'/config.php';require_login();$pdo=db();
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="network-equipment-inventory-'.date('Y-m-d').'.csv"');$out=fopen('php://output','w');fputcsv($out,['Asset Tag','Equipment Name','Category','Manufacturer','Model','Serial Number','IP Address','MAC Address','Location','Department','Assigned To','Purchase Date','Warranty Expiry','Status','Condition','Notes']);$rows=$pdo->query('SELECT asset_tag,name,category,manufacturer,model,serial_number,ip_address,mac_address,location,department,assigned_to,purchase_date,warranty_expiry,status,condition_note,notes FROM equipment ORDER BY asset_tag')->fetchAll();foreach($rows as $row)fputcsv($out,$row);fclose($out);exit;}
$total=(int)$pdo->query('SELECT COUNT(*) FROM equipment')->fetchColumn();$rows=$pdo->query('SELECT category,COUNT(*) total,SUM(CASE WHEN status="In Use" THEN 1 ELSE 0 END) in_use,SUM(CASE WHEN status="In Storage" THEN 1 ELSE 0 END) in_storage,SUM(CASE WHEN status="Under Maintenance" THEN 1 ELSE 0 END) maintenance FROM equipment GROUP BY category ORDER BY category')->fetchAll();$statuses=$pdo->query('SELECT status,COUNT(*) total FROM equipment GROUP BY status ORDER BY total DESC')->fetchAll();$warranty=$pdo->query("SELECT asset_tag,name,warranty_expiry,location FROM equipment WHERE warranty_expiry<>'' ORDER BY warranty_expiry ASC LIMIT 10")->fetchAll();$maintCost=(float)$pdo->query('SELECT COALESCE(SUM(cost),0) FROM maintenance')->fetchColumn();$pageTitle='Reports & export';require 'header.php';
?><div class="page-heading"><div><div class="eyebrow">INSIGHTS & RECORDS</div><h1>Reports & export</h1><p>Review asset distribution and maintenance summaries.</p></div><?php if(is_admin()):?><a class="btn primary" href="reports.php?export=csv">↓ Export CSV</a><?php endif;?></div><div class="stats-grid compact-stats"><div class="stat-card"><div class="stat-top"><span class="stat-icon blue">▤</span><span class="stat-caption">REGISTERED ASSETS</span></div><div class="stat-value"><?=$total?></div><div class="stat-bottom">Across all categories</div></div><div class="stat-card"><div class="stat-top"><span class="stat-icon green">↗</span><span class="stat-caption">MAINTENANCE SPEND</span></div><div class="stat-value small-value">KES <?=number_format($maintCost,2)?></div><div class="stat-bottom">Total logged maintenance cost</div></div></div><div class="report-grid"><section class="panel"><div class="panel-heading"><div><h2>Category summary</h2><p>Inventory counts grouped by equipment type</p></div></div><div class="table-wrap"><table><thead><tr><th>CATEGORY</th><th>TOTAL</th><th>IN USE</th><th>IN STORAGE</th><th>MAINTENANCE</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['category'])?></b></td><td><?=e($r['total'])?></td><td><?=e($r['in_use'])?></td><td><?=e($r['in_storage'])?></td><td><?=e($r['maintenance'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">No data available.</td></tr><?php endif;?></tbody></table></div></section><section class="panel"><div class="panel-heading"><div><h2>Status overview</h2><p>Where equipment currently stands</p></div></div><?php foreach($statuses as $s):$pct=$total?round($s['total']/$total*100):0;?><div class="category-row"><div class="category-label"><span><?=e($s['status'])?></span><b><?=e($s['total'])?></b></div><div class="progress"><span style="width:<?=$pct?>%"></span></div></div><?php endforeach;?></section></div><section class="panel warranty-panel"><div class="panel-heading"><div><h2>Warranty register</h2><p>Warranty dates recorded for equipment assets</p></div></div><div class="table-wrap"><table><thead><tr><th>ASSET</th><th>WARRANTY EXPIRY</th><th>LOCATION</th></tr></thead><tbody><?php foreach($warranty as $w):?><tr><td><b><?=e($w['name'])?></b><small class="block-muted"><?=e($w['asset_tag'])?></small></td><td><?=e($w['warranty_expiry'])?><?php if($w['warranty_expiry']<date('Y-m-d')):?> <span class="status retired">Expired</span><?php endif;?></td><td><?=e($w['location'])?></td></tr><?php endforeach;?><?php if(!$warranty):?><tr><td colspan="3" class="empty">No warranty dates have been recorded.</td></tr><?php endif;?></tbody></table></div></section><?php require 'footer.php';?>